        Update source ({count()})
      </button>
      <button type="button" onClick={() => setRecords([])}>
        Clear history
      </button>
      <ol>
        {records().map((record) => (
          <li>{record}</li>
        ))}
      </ol>
    </main>
  );
}, document.getElementById("root")!);

