import { action, createOptimistic, flush } from "solid-js";
import { render } from "@solidjs/web";

// The accessor exposes the optimistic value while the action is pending and its settled value afterward.
const [value, setValue] = createOptimistic(1);
const history = document.createElement("ol");
let release!: () => void;
const gate = new Promise<void>((resolve) => {
  release = resolve;
});
const update = action(function* () {
  setValue(2);
  yield gate;
});
let pending: Promise<unknown> | undefined;
const start = () => {
  pending = update();
  flush();
  history.insertAdjacentHTML("beforeend", `<li>Optimistic phase: ${value()}</li>`);
};
const settle = async () => {
  release();
  await pending;
  flush();
  history.insertAdjacentHTML("beforeend", `<li>After settlement: ${value()}</li>`);
};

render(() => {
  return (
    <main>
      <h3>Optimistic Signal</h3>
      <p>Current value: {value()}</p>
      <button type="button" onClick={start}>
        Start optimistic update
      </button>
      <button type="button" onClick={() => void settle()}>
        Settle action
      </button>
      {history}
    </main>
  );
}, document.getElementById("root")!);

import { createReaction, createRoot, createSignal, untrack } from "solid-js";
import { render } from "@solidjs/web";

// The tracked callback is armed explicitly and runs once for each subsequent invalidation.
const [count, setCount] = createSignal(0);
const output = document.createElement("p");
const dispose = createRoot((dispose) => {
  const track = createReaction(() => {
    const current = untrack(() => count());
    output.textContent = `Reacted to count = ${current}`;
    track(() => count());
  });
  track(() => count());
  return dispose;
});

render(() => {
  return (
    <main>
      <h3>Reaction state</h3>
      <button type="button" onClick={() => setCount((value) => value + 1)}>
        Update tracked signal
      </button>
      <button type="button" onClick={dispose}>
        Dispose reaction
      </button>
      {output}
    </main>
  );
}, document.getElementById("root")!);

