import { action, createOptimisticStore, flush } from "solid-js";
import { render } from "@solidjs/web";

render(() => {
  // Parameter 1 seeds the optimistic Store; the setter mutates a transaction-aware draft.
  const [profile, setProfile] = createOptimisticStore({ name: "Ada", visits: 1 });
