        <option value="200">200</option><option value="201">201</option><option value="202">202</option>
      </select>
      <output>Name: {envelope().value.name} | Status: {envelope().response.status} | Location: {envelope().response.headers.get("location")}</output>
    </main>
  );
}, document.getElementById("root")!);

import { clientOnly, render } from "@solidjs/web";

// The component module is requested and rendered only in the browser runtime.
const ClientGreeting = clientOnly(
  () =>
    Promise.resolve({
      default: (props: { name: string }) => <p>Client module: {props.name}</p>,
    }),
  { lazy: true },
);

render(() => {
  return (
    <main>
      <h3>Client-only component</h3>
      <ClientGreeting name="Ada" fallback={<p>Loading browser module</p>} />
    </main>
  );
}, document.getElementById("root")!);

import { createSignal } from "solid-js";
import { dynamic, render } from "@solidjs/web";

// The low-level dynamic helper resolves a reactive intrinsic element type.
render(() => {
  const [multiline, setMultiline] = createSignal(false);
  const Field = dynamic(() => (multiline() ? "textarea" : "input"));
  return (
    <main>
      <h3>Dynamic form control</h3>
      <button type="button" onClick={() => setMultiline((value) => !value)}>
        Toggle field type
      </button>
      <p>Current element: {multiline() ? "TEXTAREA" : "INPUT"}</p>
      <Field value="Dynamic component value" />
    </main>
  );
}, document.getElementById("root")!);

